     * governor limit (trigger insert already consumes 1). Instead, we build all events
     * and publish them in a single bulk Database.insert(events, false), which is 1 DML
     * statement and still returns per-record SaveResults in input order.
     *
     * @param opportunities  List of Opportunity sObjects (up to 200).
     * @return List<Database.SaveResult> in the same order as the input list.
     *         A null or empty input list returns an empty list.
     */
    public static List<Database.SaveResult> publishStageChanges(List<Opportunity> opportunities) {
        if (opportunities == null || opportunities.isEmpty()) {
            return new List<Database.SaveResult>();
        }

        List<Deal_Stage_Change__e> events = new List<Deal_Stage_Change__e>(opportunities.size());

        for (Opportunity opp : opportunities) {
            events.add(new Deal_Stage_Change__e(
                Opportunity_Id__c = opp.Id,
                Stage__c          = opp.StageName,
                Amount__c         = opp.Amount
            ));
        }

        // Single DML statement; returns per-record SaveResults in the same order as `events`.
        // `false` ensures one failed insert doesn't abort the rest.
        return Database.insert(events, false);
    }
