/**
 * Before-insert handler for OpportunityLineItem.
 *
 * Sets the standard discount (from PricingRules) on any new line whose
 * Discount is still null.  Lines that already carry a Discount – including 0 –
 * are left untouched.
 *
 * Governor-limit strategy
 * -----------------------
 * PricingRules.standardDiscountFor(Id) performs a SOQL internally, so calling
 * it per line would exceed the 100-query limit on a 200-line CPQ batch.
 *
 * Instead we:
 *   1. Collect the distinct Product2Ids that actually need a default.
 *   2. Issue ONE batched SOQL to fetch their Family values.
 *   3. Call PricingRules.standardDiscountForFamily(family) per line – a pure
 *      if/else method with zero SOQL.
 *
 * The business rules remain exclusively in PricingRules; this handler only
 * orchestrates the lookup and assignment.
 */
public without sharing class LineItemDiscountHandler {

    public static void onBeforeInsert(List<OpportunityLineItem> newOLI) {
        if (newOLI == null || newOLI.isEmpty()) {
            return;
        }

        // ---- Phase 1: gather unique Product2Ids that need a default discount
        Set<Id> productsToResolve = new Set<Id>();

        for (OpportunityLineItem oli : newOLI) {
            if (oli.Discount == null && oli.Product2Id != null) {
                productsToResolve.add(oli.Product2Id);
            }
        }

        // ---- Phase 2: single batched SOQL to resolve Family per product
        Map<Id, String> familyByProduct = new Map<Id, String>();

        if (!productsToResolve.isEmpty()) {
            for (Product2 p : [SELECT Id, Family FROM Product2 WHERE Id IN :productsToResolve]) {
                familyByProduct.put(p.Id, p.Family);
            }
        }

        // ---- Phase 3: apply the standard discount to each qualifying line
        // standardDiscountForFamily is pure logic (no SOQL), safe to call per line.
        for (OpportunityLineItem oli : newOLI) {
            if (oli.Discount == null) {
                String family = (oli.Product2Id != null)
                    ? familyByProduct.get(oli.Product2Id)
                    : null;
                oli.Discount = PricingRules.standardDiscountForFamily(family);
            }
        }
    }
}
```

