trigger CaseTrigger on Case (after update) {
    // Collect case ids that transitioned from not-closed to closed and have a contact.
    List<Id> surveyCaseIds = new List<Id>();

    for (Case c : Trigger.new) {
        Case oldC = Trigger.oldMap.get(c.Id);
        if (c.IsClosed && !oldC.IsClosed && c.ContactId != null) {
            surveyCaseIds.add(c.Id);
        }
    }

    // Enqueue dispatcher jobs in chunks of 50 to respect the
    // 50-queueable-jobs-per-transaction limit.  Each dispatcher will
    // fan out into individual worker jobs (one per case) in its own
    // transaction, so a single failure cannot affect the others.
    for (Integer i = 0; i < surveyCaseIds.size(); i += 50) {
        List<Id> chunk = new List<Id>();
        Integer chunkEnd = Math.min(i + 50, surveyCaseIds.size());
        for (Integer j = i; j < chunkEnd; j++) {
            chunk.add(surveyCaseIds[j]);
        }
        System.enqueueJob(new CaseSurveyJob(chunk));
    }
}
