public class CaseSurveyJob implements Queueable {

    private List<Id> caseIds;

    /**
     * Single-case constructor – useful when enqueuing from a button,
     * flow, or another integration point.
     */
    public CaseSurveyJob(Id caseId) {
        caseIds = new List<Id>{ caseId };
    }

    /**
     * Multi-case constructor – used by the trigger and by the
     * chaining step inside execute().
     */
    public CaseSurveyJob(List<Id> ids) {
        caseIds = ids;
    }

    public void execute(QueueableContext context) {
        if (caseIds == null || caseIds.isEmpty()) {
            return;
        }

        // --- Process exactly ONE case in this transaction ---
        Case c = [SELECT Id, CaseNumber, ContactId FROM Case WHERE Id = :caseIds[0]];

        if (c.ContactId != null) {
            Task t = new Task(
                WhatId       = c.Id,
                WhoId        = c.ContactId,
                Subject      = 'CSAT survey: ' + c.CaseNumber,
                ActivityDate = Date.today().addDays(2),
                Status       = 'Not Started'
            );
            insert t;
        }

        // --- Chain: enqueue the next job for remaining cases ---
        // At most one job is enqueued per execute(), so the 50-jobs
        // per-transaction limit is never exceeded regardless of list size.
        if (caseIds.size() > 1) {
            List<Id> remaining = new List<Id>();
            for (Integer i = 1; i < caseIds.size(); i++) {
                remaining.add(caseIds[i]);
            }
            System.enqueueJob(new CaseSurveyJob(remaining));
        }
    }
}
