public class CaseSurveyJob implements Queueable, Database.Batchable {

    private final List<Id> caseIds;

    public CaseSurveyJob(List<Id> caseIds) {
        this.caseIds = caseIds;
    }

    // ===================== Queueable =====================

    public void execute(QueueableContext context) {
        // Process the first case in this transaction
        Case c = [SELECT Id, CaseNumber, ContactId FROM Case WHERE Id = :caseIds[0]];
        if (c.ContactId != null) {
            insert new Task(
                WhatId       = c.Id,
                WhoId        = c.ContactId,
                Subject      = 'CSAT survey: ' + c.CaseNumber,
                ActivityDate = Date.today().addDays(2),
                Status       = 'Not Started'
            );
        }

        // Delegate remaining cases to a batch job (1 case per batch
        // transaction → full isolation without hitting the 50-job
        // limit or the async stack-depth limit).
        if (caseIds.size() > 1) {
            List<Id> remaining = new List<Id>(caseIds.sublist(1, caseIds.size()));
            Database.executeBatch(new CaseSurveyJob(remaining), 1);
        }
    }

    // ===================== Batchable =====================

    public Database.QueryLocator start(Database.BatchableContext bc) {
        return Database.getQueryLocator(
            [SELECT Id, CaseNumber, ContactId FROM Case WHERE Id IN :caseIds]
        );
    }

    public void execute(Database.BatchableContext bc, SObject[] scope) {
        for (Case c : (List<Case>) scope) {
            if (c.ContactId == null) {
                continue;
            }
            insert new Task(
                WhatId       = c.Id,
                WhoId        = c.ContactId,
                Subject      = 'CSAT survey: ' + c.CaseNumber,
                ActivityDate = Date.today().addDays(2),
                Status       = 'Not Started'
            );
        }
    }

    public void finish(Database.BatchableContext bc) {
        // No post-processing needed
    }
}
