public class RenewalReminderService {

    /**
     * The platform allows at most 10 Messaging.sendEmail invocations per
     * Apex transaction.  By sending up to 20 emails per invocation we can
     * handle the full 200-record batch in exactly 10 invocations.
     */
    private static final Integer EMAILS_PER_INVOCATION = 20;

    /**
     * Sends a renewal-reminder email to the owner of each given opportunity.
     *
     * Emails are grouped into batches of EMAILS_PER_INVOCATION so that the
     * 10-invocation-per-transaction governor limit is never exceeded while
     * still handling up to 200 opportunities in a single call.  If one
     * email in a batch fails (bad address, etc.) the remaining emails in
     * that batch are still delivered because Messaging.sendEmail processes
     * the entire array and returns a per-message result.
     *
     * @param opportunityIds  Up to 200 Opportunity Ids.
     * @return The number of emails delivered successfully.
     */
    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        // Single bulk SOQL – safe for up to 200 Ids.
        List<Opportunity> opportunities = [
            SELECT Id, Name, CloseDate, OwnerId
            FROM Opportunity
            WHERE Id IN :opportunityIds
              AND OwnerId != null
        ];

        if (opportunities.isEmpty()) {
            return 0;
        }

        Integer sentCount = 0;
        List<Messaging.SingleEmailMessage> batch =
            new List<Messaging.SingleEmailMessage>();

        for (Opportunity opp : opportunities) {
            Messaging.SingleEmailMessage mail =
                new Messaging.SingleEmailMessage();
            mail.setTargetObjectId(opp.OwnerId);
            mail.setSaveAsActivity(false);
            mail.setSubject('Renewal due: ' + opp.Name);
            mail.setPlainTextBody(
                'Hello,\n\n' +
                'The opportunity "' + opp.Name + '" is due for renewal.\n' +
                'Close date: ' + opp.CloseDate.format() + '\n\n' +
                'Please review and take the necessary renewal action.\n\n' +
                'Regards'
            );
            batch.add(mail);

            // Flush every EMAILS_PER_INVOCATION emails to stay within
            // the 10-invocation governor limit.
            if (batch.size() >= EMAILS_PER_INVOCATION) {
                sentCount += flushBatch(batch);
                batch.clear();
            }
        }

        // Send any remaining emails.
        if (!batch.isEmpty()) {
            sentCount += flushBatch(batch);
        }

        return sentCount;
    }

    /**
     * Sends one batch of emails in a single Messaging.sendEmail call and
     * returns how many were delivered successfully.
     */
    private static Integer flushBatch(List<Messaging.SingleEmailMessage> batch) {
        Integer delivered = 0;
        try {
            Messaging.EmailResult[] results = Messaging.sendEmail(batch);
            for (Messaging.EmailResult r : results) {
                if (r.isSuccess()) {
                    delivered++;
                }
            }
        } catch (Exception e) {
            // Log and continue so a systemic failure in one batch does not
            // prevent subsequent batches from being attempted.
            System.debug(LoggingLevel.ERROR,
                'RenewalReminderService: batch send failed – ' + e.getMessage());
        }
        return delivered;
    }
}
