        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>(
            [SELECT Id, Name, CloseDate, OwnerId
             FROM Opportunity
             WHERE Id IN :opportunityIds]
        );

        Integer sentCount = 0;

        for (Id oppId : opportunityIds) {
            Opportunity opp = oppMap.get(oppId);
            if (opp == null || opp.OwnerId == null) {
                continue; // not found or unowned – skip silently
            }

            try {
                Messaging.SingleEmailMessage email = new Messaging.SingleEmailMessage();
                email.setTargetObjectId(opp.OwnerId);
                email.setSaveAsActivity(false);
                email.setSubject('Renewal due: ' + opp.Name);
                email.setPlainTextBody(
                    'Hello,\n\n'
                    + 'Your opportunity "' + opp.Name + '" has a close date of '
                    + opp.CloseDate
                    + '. Please follow up with the customer to confirm the renewal.\n\n'
                    + 'Thanks'
                );

                // One sendEmail call per opportunity so a single failure
                // does not cascade to the rest.
                List<Messaging.SendEmailResult> results =
                    Messaging.sendEmail(new List<Messaging.SingleEmailMessage>{ email });

                if (results != null && !results.isEmpty() && results[0].isSuccess()) {
                    sentCount++;
                } else {
                    System.debug(LoggingLevel.WARN,
